import importlib, subprocess, sys as _sys

def _ensure(pkg):
    try:
        importlib.import_module(pkg)
    except ImportError:
        print(f"  📦 Instalando {pkg}...")
        subprocess.check_call([_sys.executable, "-m", "pip", "install", pkg, "-q"])

_ensure("openpyxl")
_ensure("pandas")
