# ══════════════════════════════════════════════════════════════════════
#  FECHA
# ══════════════════════════════════════════════════════════════════════

def detectar_fecha(nombre: str) -> dict:
    meses_inv = {v.upper():k for k,v in MESES_ES.items()}
    m = re.search(r'(\d{1,2})[-_\s]([A-Z]+)[-_\s](\d{4})',
                  os.path.basename(nombre).upper())
    if m:
        dia, mes_str, anio = int(m.group(1)), m.group(2), int(m.group(3))
        mes_num = meses_inv.get(mes_str)
        if mes_num:
            if dia == 1:
                mc = mes_num - 1 if mes_num > 1 else 12
                ac = anio if mes_num > 1 else anio - 1
            else:
                mc, ac = mes_num, anio
            return {"dia": DIAS_FIN_MES[mc], "mes": mc, "anio": ac}
    hoy = datetime.today()
    mc = hoy.month - 1 if hoy.month > 1 else 12
    ac = hoy.year if hoy.month > 1 else hoy.year - 1
    return {"dia": DIAS_FIN_MES[mc], "mes": mc, "anio": ac}


def textos_fecha(f: dict) -> dict:
    d, m, a = f["dia"], f["mes"], f["anio"]
    mn = MESES_ES[m]; trim = TRIMESTRES[m]
    return {
        "dia_mes_anio": f"{d} de {mn} de {a}",
        "DIA_MES_ANIO": f"{d} DE {mn.upper()} DE {a}",
        "trimestre": trim, "anio": str(a), "mes": m,
        "fuente_map": f"Módulo de Adecuaciones Presupuestarias (MAP) {a}, cifras al {d} de {mn} de {a}.",
    }

# ══════════════════════════════════════════════════════════════════════
#  LECTURA CSV
# ══════════════════════════════════════════════════════════════════════

def leer_csv_map(path: str, mes_corte: int) -> dict:
    print(f"  📊 Procesando CSV (corte mes {mes_corte})...")
    try:
        df = pd.read_csv(path, encoding='utf-8')
    except UnicodeDecodeError:
        df = pd.read_csv(path, encoding='latin-1')

    df['PP']  = df['IDEN_PROY'].astype(str) + df['PROYECTO'].astype(str).str.zfill(3)
    df['CAP'] = df['PARTIDA'].apply(lambda p: CAP_MAP.get(int(p)//1000, 0)
                                    if str(p).isdigit() or (isinstance(p,(int,float)) and not pd.isna(p)) else 0)

    df_sc = df[df['UNIDAD'].astype(str).str.match(r'^\d{3}$', na=False)].copy()
    df_sc = df_sc[df_sc['PP'].isin(PP_NOMBRES.keys())]

    mp = MESES_COLS[:mes_corte]
    ma = MESES_COLS

    df_sc['ORI_ANUAL'] = df_sc[[f'ORI_{m}' for m in ma]].sum(axis=1)
    df_sc['MOD_ANUAL'] = df_sc[[f'MOD_{m}' for m in ma]].sum(axis=1)
    df_sc['ORI_P']     = df_sc[[f'ORI_{m}' for m in mp]].sum(axis=1)
    df_sc['MOD_P']     = df_sc[[f'MOD_{m}' for m in mp]].sum(axis=1)
    df_sc['EJE_P']     = df_sc[[f'EJE_{m}' for m in mp]].sum(axis=1)
    df_sc['DISP_P']    = df_sc['MOD_P'] - df_sc['EJE_P']

    MDP = 1_000_000

    pp_grp = df_sc.groupby('PP')[['ORI_ANUAL','MOD_ANUAL','ORI_P','MOD_P','EJE_P','DISP_P']].sum() / MDP
    tot = pp_grp.sum()
    pp_rows = {pp: dict(original_anual=r['ORI_ANUAL'], modificado_anual=r['MOD_ANUAL'],
                        original_p=r['ORI_P'], modificado_p=r['MOD_P'],
                        ejercido=r['EJE_P'], disponible=r['DISP_P'])
               for pp, r in pp_grp.iterrows()}
    pp_rows["Total general"] = dict(original_anual=tot['ORI_ANUAL'], modificado_anual=tot['MOD_ANUAL'],
                                    original_p=tot['ORI_P'], modificado_p=tot['MOD_P'],
                                    ejercido=tot['EJE_P'], disponible=tot['DISP_P'])

    cap_grp = df_sc.groupby('CAP')[['ORI_ANUAL','MOD_ANUAL','ORI_P','MOD_P','EJE_P','DISP_P']].sum() / MDP
    cap_dict = {c: dict(original_anual=r['ORI_ANUAL'], modificado_anual=r['MOD_ANUAL'],
                        original_p=r['ORI_P'], modificado_p=r['MOD_P'],
                        ejercido=r['EJE_P'], disponible=r['DISP_P'])
                for c, r in cap_grp.iterrows() if c in CAPITULOS}

    pc_grp = df_sc.groupby(['PP','CAP'])[['ORI_ANUAL','MOD_ANUAL','ORI_P','MOD_P','EJE_P']].sum() / MDP
    pp_cap = {(pp, c): dict(original_anual=r['ORI_ANUAL'], modificado_anual=r['MOD_ANUAL'],
                            original_p=r['ORI_P'], modificado_p=r['MOD_P'], ejercido=r['EJE_P'])
              for (pp, c), r in pc_grp.iterrows() if c in CAPITULOS}

    bloques = _bloques_csv(df_sc)
    return dict(pp=pp_rows, cap=cap_dict, pp_cap=pp_cap,
                cap_com=cap_dict, bloques=bloques)


def _bloques_csv(df_sc: pd.DataFrame) -> dict:
    bloques = {}
    for cap in CAPITULOS:
        dc = df_sc[df_sc['CAP'] == cap]
        if dc.empty:
            bloques[cap] = {"partidas": []}
            continue
        pg = dc.groupby('PARTIDA')['DISP_P'].sum().reset_index()
        pg = pg[pg['DISP_P'] > 0].sort_values('DISP_P', ascending=False)
        total = pg['DISP_P'].sum()
        if total == 0:
            bloques[cap] = {"partidas": []}
            continue
        pg['PCT'] = pg['DISP_P'] / total
        bloques[cap] = {"partidas": [dict(clave=int(r['PARTIDA']),
                                          nombre=NOMBRES_PARTIDAS.get(int(r['PARTIDA']),
                                                                       f"Partida {int(r['PARTIDA'])}"),
                                          pct=r['PCT'])
                                     for _, r in pg.iterrows()]}
    return bloques

# ══════════════════════════════════════════════════════════════════════
#  LECTURA XLSX
# ══════════════════════════════════════════════════════════════════════

def _sf(v):
    try: return 0.0 if pd.isna(v) else float(v)
    except: return 0.0

def leer_xlsx_map(path: str) -> dict:
    print("  📊 Procesando xlsx con hojas TD...")
    import openpyxl as _opxl
    xl = pd.ExcelFile(path)
    hojas = xl.sheet_names
    print(f"  📋 Hojas: {hojas}")
    # Abrir con openpyxl una sola vez para lectura de columnas con nombre
    _wb = _opxl.load_workbook(path, data_only=True, read_only=True)

    def td(kws):
        for h in hojas:
            if all(k.upper() in h.upper() for k in kws):
                return pd.read_excel(path, sheet_name=h, header=None)
        return pd.DataFrame()

    # Cargar las 4 TDs
    df_pp  = td(["TD","Pp"])             # shape (11,5)  col0=PP, 1=ORI_A,2=MOD_A,3=MOD_P,4=EJE
    df_cap = td(["TD","CAP"])            # shape (33,7)  ver abajo
    df_agr = td(["TD","AGRICULTURA"])    # shape (195,13) col0=CAP,1=ORI_A,2=MOD_A,3=MOD_P,4=EJE,5=DISP
    df_com = td(["TD","Comisario"])      # shape (140,154) col0=PP,1=ORI_A,2=MOD_A,3=ORI_P,4=MOD_P,5=EJE,6=DISP

    # ── TD Pp: col0=PP, 1=ORI_A, 2=MOD_A, 3=MOD_P, 4=EJE ─────────
    pp_rows = {}
    for i in range(len(df_pp)):
        k = str(df_pp.iloc[i, 0]).strip()
        if k in PP_NOMBRES or k == "Total general":
            mod_p = _sf(df_pp.iloc[i, 3])
            eje   = _sf(df_pp.iloc[i, 4])
            pp_rows[k] = dict(
                original_anual  = _sf(df_pp.iloc[i, 1]),
                modificado_anual = _sf(df_pp.iloc[i, 2]),
                original_p      = mod_p,   # se sobreescribe con TD Comisario
                modificado_p    = mod_p,
                ejercido        = eje,
                disponible      = mod_p - eje,
            )

    # ── TD AGRICULTURA global: col0=CAP,1=ORI_A,2=MOD_A,3=MOD_P,4=EJE,5=DISP
    cap_dict = {}
    for i in range(len(df_agr)):
        try:
            c = int(float(str(df_agr.iloc[i, 0])))
            if c in CAPITULOS:
                mod_p = _sf(df_agr.iloc[i, 3])
                eje   = _sf(df_agr.iloc[i, 4])
                disp  = _sf(df_agr.iloc[i, 5])
                cap_dict[c] = dict(
                    original_anual  = _sf(df_agr.iloc[i, 1]),
                    modificado_anual = _sf(df_agr.iloc[i, 2]),
                    original_p      = mod_p,
                    modificado_p    = mod_p,
                    ejercido        = eje,
                    disponible      = disp,
                )
        except: pass

    # ── TD Pp y CAP: dos bloques ───────────────────────────────────
    # Bloque 1 (filas 4-9): col1=CAP,2=ORI_A,3=MOD_A,4=MOD_P,5=EJE  (global)
    # Bloque 2 (filas 16+): col0=clave(PP+CAP),1=PP,2=CAP,3=ORI_A,4=MOD_A,5=MOD_P,6=EJE
    pp_cap = {}
    for i in range(len(df_cap)):
        combo = str(df_cap.iloc[i, 0]).strip()
        # Bloque 2: col0 es clave tipo "P0211000", col1=PP, col2=CAP
        if len(combo) >= 7 and combo[:4] in PP_NOMBRES:
            pp_k = combo[:4]
            try:
                c = int(float(str(df_cap.iloc[i, 2])))
                if c in CAPITULOS:
                    mod_p = _sf(df_cap.iloc[i, 5])
                    eje   = _sf(df_cap.iloc[i, 6])
                    pp_cap[(pp_k, c)] = dict(
                        original_anual  = _sf(df_cap.iloc[i, 3]),
                        modificado_anual = _sf(df_cap.iloc[i, 4]),
                        original_p      = mod_p,
                        modificado_p    = mod_p,
                        ejercido        = eje,
                        disponible      = mod_p - eje,
                    )
            except: pass

    # ── TD Comisario por Pp: first occurrence only (avoid zero overwrites)
    seen_com = set()
    for i in range(len(df_com)):
        k = str(df_com.iloc[i, 0]).strip()
        if (k in PP_NOMBRES or k == "Total general") and k not in seen_com:
            ori_p = _sf(df_com.iloc[i, 3])
            seen_com.add(k)
            if k in pp_rows:
                pp_rows[k]['original_p'] = ori_p

    # ── TD Comisario caps: leer bloque 1 por columnas CQ/CT/CU/CV ────
    # CQ=col95, CT=col98=ORIGINAL_P, CU=col99=MODIFICADO_P, CV=col100=EJERCIDO, CW=col101=DISP
    # (índices 0-based: CQ=94, CT=97, CU=98, CV=99, CW=100)
    cap_com = {}
    try:
        _ws_td = _wb['TD Presupuesto Comisario']
        for row in _ws_td.iter_rows():
            row = list(row)
            if len(row) <= 100: continue
            cq_val = row[94].value  # col CQ
            if cq_val in CAPITULOS and cq_val not in cap_com:
                cap_com[int(cq_val)] = dict(
                    original_p  = _sf(row[97].value),   # CT
                    modificado_p= _sf(row[98].value),   # CU
                    ejercido    = _sf(row[99].value),   # CV
                    disponible  = _sf(row[100].value),  # CW
                )
    except Exception as _e:
        print(f"  ⚠️  cap_com: {_e}")
    finally:
        _wb.close()

    bloques = _bloques_td(df_agr)

    # ── Bloques por Pp del TD Comisario (para justificaciones cuadro 1) ──
    # OJO: no todos los bloques de Pp tienen el mismo número de filas de
    # filtro arriba (algunos traen un filtro extra 'TIPO UR 1' antes de
    # 'PP', otros no), así que la fila de 'PP' varía de un bloque a otro.
    # Por eso se busca 'PP' en un RANGO de filas (no una fila fija) y todo
    # lo demás (pct_total, encabezado, datos, texto ya formado) se calcula
    # en relación a la fila donde realmente se encontró 'PP'.
    bloques_pp = {}

    def _leer_bloque_pp(ws, r0, sc, max_filas=140):
        """r0 = fila donde se encontró 'PP', sc = columna de esa celda."""
        pp = ws.cell(r0, sc + 1).value
        if pp is None:
            return None
        pp = str(pp).strip()
        if pp not in PP_NOMBRES:
            return None

        # Primero localizar la fila de encabezado ('Etiquetas de fila').
        header_row = None
        for dr in range(1, 7):
            if str(ws.cell(r0 + dr, sc).value or '').strip() == 'Etiquetas de fila':
                header_row = r0 + dr
                break
        if header_row is None:
            header_row = r0 + 2  # fallback razonable si no se encontró

        # El % total de variación del bloque vive en alguna fila ENTRE la
        # fila de 'PP' y la fila de encabezado (nunca dentro del área de
        # datos, donde también hay valores de % por partida individual).
        pct_total = 0.0
        for r in range(r0 + 1, header_row):
            v = ws.cell(r, sc + 5).value
            if isinstance(v, (int, float)) and 0 < v <= 1.5:
                pct_total = float(v)

        data_start = header_row + 1
        parts, total_all = [], 0.0
        texto_just, texto_len_max = None, 0
        vacias_seguidas = 0
        for r in range(data_start, data_start + max_filas):
            partida = ws.cell(r, sc + 3).value
            if partida is None:
                vacias_seguidas += 1
                if vacias_seguidas > 2:
                    break
                continue
            vacias_seguidas = 0
            if str(partida).strip() == 'Total general':
                break
            monto  = ws.cell(r, sc + 4).value
            nombre = ws.cell(r, sc + 6).value
            m = float(monto or 0)
            if m > 0:
                total_all += m
                parts.append({'clave': partida, 'nombre': str(nombre or '').strip(), 'monto': m})
            # El texto de justificación ya formado (comas + varias partidas)
            # aparece "congelado" en alguna fila del bloque — nos quedamos
            # con el más largo encontrado en vez de asumir una fila fija.
            txt = ws.cell(r, sc + 7).value
            if isinstance(txt, str) and ',' in txt and len(txt) > texto_len_max:
                texto_just, texto_len_max = txt.strip(), len(txt)

        parts.sort(key=lambda x: x['monto'], reverse=True)
        for p in parts:
            p['pct'] = p['monto'] / total_all if total_all else 0

        return {'pp': pp, 'pct_total': pct_total, 'partidas': parts,
                'total_all': total_all, 'texto_just': texto_just}

    try:
        _wb2 = _opxl.load_workbook(path, data_only=True, read_only=True)
        _ws_com = _wb2['TD Presupuesto Comisario']
        cols_vistas = set()
        # Rango razonable de filas donde puede aparecer la etiqueta 'PP'
        # de cada bloque (en vez de asumir una única fila fija).
        for row_idx in range(20, 40):
            fila = _ws_com[row_idx] if row_idx <= _ws_com.max_row else []
            for c in fila:
                if c.value == 'PP' and c.column not in cols_vistas:
                    cols_vistas.add(c.column)
                    info = _leer_bloque_pp(_ws_com, row_idx, c.column)
                    if info:
                        bloques_pp[info['pp']] = info
                    else:
                        print(f"  ⚠️  bloques_pp: no se pudo leer el bloque en fila {row_idx}, columna {c.column}")
        _wb2.close()
    except Exception as _e2:
        print(f"  ⚠️  bloques_pp: {_e2}")

    return dict(pp=pp_rows, cap=cap_dict, pp_cap=pp_cap,
                cap_com=cap_com, bloques=bloques, bloques_pp=bloques_pp)


def _bloques_td(df: pd.DataFrame) -> dict:
    bloques = {}
    if df.empty:
        for c in CAPITULOS: bloques[c] = {"partidas": []}
        return bloques
    for cap in CAPITULOS:
        parts = []
        in_b = False
        for i in range(len(df)):
            r = df.iloc[i]
            if str(r[0]) == "CAPÍTULO" and r[1] == cap:
                in_b = True; continue
            if in_b:
                cv = r[3] if df.shape[1]>3 else None
                pv = r[5] if df.shape[1]>5 else None
                nv = r[7] if df.shape[1]>7 else None
                if str(cv) in ["nan","PARTIDA","Etiquetas de fila"]: continue
                try:
                    cl = int(float(str(cv)))
                    pc = float(pv) if pd.notna(pv) else 0.0
                    nm = str(nv).strip() if pd.notna(nv) else NOMBRES_PARTIDAS.get(cl, f"Partida {cl}")
                    parts.append(dict(clave=cl, nombre=nm, pct=pc))
                except:
                    if parts: break
        bloques[cap] = {"partidas": parts}
    return bloques

# ══════════════════════════════════════════════════════════════════════
#  MOTIVOS
# ══════════════════════════════════════════════════════════════════════

def motivo_cap(bloque: dict, n: int = 5) -> str:
    parts = bloque.get("partidas", [])[:n]
    if not parts: return ""
    pct = sum(p["pct"] for p in parts)
    noms = [f"{p['clave']} {p['nombre']}" for p in parts]
    return f"El {pct*100:.1f}% de la variación se observa en las partidas:\n{', '.join(noms)}."

def motivo_pp(bloque_pp: dict, n: int = 5) -> str:
    """Genera el texto de justificación para un Pp del Comisario."""
    if not bloque_pp: return ""
    pct_total  = bloque_pp.get('pct_total') or 0
    texto_just = bloque_pp.get('texto_just', '')

    # Usar el texto pre-calculado del TD si existe (es el más preciso)
    if texto_just and pct_total:
        # Limpiar comas finales sueltas
        texto_limpio = texto_just.rstrip(', .')
        return (f"El {pct_total*100:.1f} % de la variación se observa en las partidas:\n"
                f"{texto_limpio}.")

    # Fallback: construir desde partidas con nombre ordenadas por monto
    parts_con_nombre = [p for p in bloque_pp.get('partidas', [])
                        if str(p.get('nombre', '')).strip()]
    parts = parts_con_nombre[:n]
    if not parts: return ""
    pct_show = pct_total if pct_total else sum(p.get('pct', 0) for p in parts)
    noms = [f"{p['clave']} {str(p['nombre']).strip()}" for p in parts]
    return f"El {pct_show*100:.1f} % de la variación se observa en las partidas:\n{', '.join(noms)}."

def motivo_cap4000(datos: dict, tf: dict) -> str:
    lineas = []
    for k in ["S318","S292","S304","S293"]:
        d = datos["pp"].get(k, {})
        disp = d.get("disponible", 0)
        if disp > 0:
            n = PP_NOMBRES[k].split(" - ")[1]
            lineas.append(f"{k} {n}: {disp:,.3f} mdp")
    if lineas:
        return (f"La disponibilidad está distribuida de la siguiente manera:\n"
                f"El Disponible al {tf['dia_mes_anio']} se encuentra en la partida 43101; "
                + "; ".join(lineas) + ".")
    return "El disponible del Capítulo 4000 está en la partida 43101."

# ══════════════════════════════════════════════════════════════════════
#  COPIAR HOJA COMPLETA
# ══════════════════════════════════════════════════════════════════════

def _copy_sheet(ws_src, ws_dst):
    for col, cd in ws_src.column_dimensions.items():
        ws_dst.column_dimensions[col].width = cd.width
    for row, rd in ws_src.row_dimensions.items():
        ws_dst.row_dimensions[row].height = rd.height
    for mg in ws_src.merged_cells.ranges:
        ws_dst.merge_cells(str(mg))

    # Collect which cells are merge slaves (not top-left)
    merge_slaves = set()
    for mg in ws_src.merged_cells.ranges:
        cells = list(mg.cells)
        for r, c in cells[1:]:
            merge_slaves.add((r, c))

    for row in ws_src.iter_rows():
        for sc in row:
            if (sc.row, sc.column) in merge_slaves:
                continue
            dc = ws_dst.cell(row=sc.row, column=sc.column)
            dc.value = sc.value
            if sc.has_style:
                dc.font           = copy(sc.font)
                dc.border         = copy(sc.border)
                dc.fill           = copy(sc.fill)
                dc.number_format  = sc.number_format
                dc.alignment      = copy(sc.alignment)

    # ── Autoajuste de ancho de columnas ──────────────────────────────
    # Calcula el ancho máximo del contenido real de cada columna,
    # respetando un mínimo de 8 y un máximo de 60 caracteres.
    from openpyxl.utils import get_column_letter

    # Columnas que pertenecen a celdas combinadas (no autoajustar)
    merged_cols = set()
    for mg in ws_dst.merged_cells.ranges:
        # Solo ignorar columnas donde el merge abarca más de 1 columna
        if mg.min_col != mg.max_col:
            for c in range(mg.min_col, mg.max_col + 1):
                merged_cols.add(c)

    col_widths: dict = {}
    for row in ws_dst.iter_rows():
        for cell in row:
            if cell.column in merged_cols:
                continue
            if cell.value is None:
                continue
            # Tomar la línea más larga si hay saltos de línea
            val_str = str(cell.value)
            max_line = max((len(line) for line in val_str.split('\n')), default=0)
            # Ajuste por tamaño de fuente (aproximación: factor 1.2 para fuentes >11)
            font_size = cell.font.size if cell.font and cell.font.size else 11
            adjusted = max_line * (1.15 if font_size > 11 else 1.0)
            if cell.column not in col_widths or adjusted > col_widths[cell.column]:
                col_widths[cell.column] = adjusted

    for col_idx, width in col_widths.items():
        col_letter = get_column_letter(col_idx)
        # Respetar ancho mínimo de 8 y máximo de 55
        final_width = max(8.0, min(55.0, width + 2))
        # Solo actualizar si el autoajuste es mayor que el ancho actual de la plantilla
        current = ws_dst.column_dimensions[col_letter].width or 0
        if final_width > current:
            ws_dst.column_dimensions[col_letter].width = final_width

# ══════════════════════════════════════════════════════════════════════
#  HOJA Pp
# ══════════════════════════════════════════════════════════════════════

def _var(a, b):
    """% variación (b-a)/a, 0 si a==0"""
    try:
        return (b - a) / a if a and a != 0 else 0.0
    except: return 0.0


def hoja_pp(wb_out, datos, tf, tpl):
    wb = _get_template(tpl)
    ws = wb['Pp']
    pp = datos["pp"]

    ws['B1']  = f"Avance en el ejercicio del presupuesto {tf['anio']} del Sector Central de AGRICULTURA"
    ws['B5']  = f"Cifras con corte al cierre del {tf['trimestre']} de {tf['anio']}"
    ws['G6']  = f"Corte al {tf['dia_mes_anio']}"
    ws['B23'] = f"Fuente: {tf['fuente_map']}"

    def set_pp_row(fila, pp_k):
        d = pp.get(pp_k, {})
        orig  = d.get("original_anual", 0) or 0
        mod   = d.get("modificado_anual", 0) or 0
        mod_p = d.get("modificado_p", d.get("original_p", 0)) or 0
        ejrc  = d.get("ejercido", 0) or 0
        ws.cell(fila, 4).value = orig
        ws.cell(fila, 5).value = mod
        ws.cell(fila, 6).value = _var(orig, mod)
        ws.cell(fila, 7).value = mod_p
        ws.cell(fila, 8).value = ejrc
        ws.cell(fila, 9).value = _var(mod_p, ejrc)
        return orig, mod, mod_p, ejrc

    # Pp individuales
    subsidios = ["S292","S293","S304","S318"]
    pp_filas = [("S292",14),("S293",15),("S304",16),("S318",17),
                ("K017",19),("P021",21),("M001",22)]
    totales = {k: set_pp_row(f, k) for k, f in pp_filas}

    # Subtotal Subsidios (fila 13): suma S292+S293+S304+S318
    ws.cell(13, 4).value = sum(totales[k][0] for k in subsidios if k in totales)
    ws.cell(13, 5).value = sum(totales[k][1] for k in subsidios if k in totales)
    ws.cell(13, 6).value = _var(ws.cell(13,4).value, ws.cell(13,5).value)
    ws.cell(13, 7).value = sum(totales[k][2] for k in subsidios if k in totales)
    ws.cell(13, 8).value = sum(totales[k][3] for k in subsidios if k in totales)
    ws.cell(13, 9).value = _var(ws.cell(13,7).value, ws.cell(13,8).value)

    # Subtotal Inversión K017 (fila 18)
    t_k017 = totales.get("K017", (0,0,0,0))
    ws.cell(18, 4).value = t_k017[0]; ws.cell(18, 5).value = t_k017[1]
    ws.cell(18, 6).value = _var(t_k017[0], t_k017[1])
    ws.cell(18, 7).value = t_k017[2]; ws.cell(18, 8).value = t_k017[3]
    ws.cell(18, 9).value = _var(t_k017[2], t_k017[3])

    # Subtotal Administrativos P021+M001 (fila 20)
    adm = ["P021","M001"]
    ws.cell(20, 4).value = sum(totales[k][0] for k in adm if k in totales)
    ws.cell(20, 5).value = sum(totales[k][1] for k in adm if k in totales)
    ws.cell(20, 6).value = _var(ws.cell(20,4).value, ws.cell(20,5).value)
    ws.cell(20, 7).value = sum(totales[k][2] for k in adm if k in totales)
    ws.cell(20, 8).value = sum(totales[k][3] for k in adm if k in totales)
    ws.cell(20, 9).value = _var(ws.cell(20,7).value, ws.cell(20,8).value)

    # Total general (fila 12): suma de subtotales 13+18+20
    for col in [4,5,7,8]:
        ws.cell(12, col).value = (ws.cell(13,col).value + ws.cell(18,col).value
                                  + ws.cell(20,col).value)
    ws.cell(12, 6).value = _var(ws.cell(12,4).value, ws.cell(12,5).value)
    ws.cell(12, 9).value = _var(ws.cell(12,7).value, ws.cell(12,8).value)
    # Número de Pp total
    ws.cell(12, 3).value = sum(ws.cell(r,3).value or 0
                               for r in [13,18,20] if ws.cell(r,3).value)

    if 'Pp' in wb_out.sheetnames: del wb_out['Pp']
    ws_n = wb_out.create_sheet('Pp')
    _copy_sheet(ws, ws_n)

# ══════════════════════════════════════════════════════════════════════
#  HOJA Pp y CAP
# ══════════════════════════════════════════════════════════════════════

def hoja_pp_cap(wb_out, datos, tf, tpl):
    wb = _get_template(tpl)
    ws = wb['Pp y CAP']
    cap  = datos["cap"]
    pp   = datos["pp"]
    pc   = datos["pp_cap"]

    ws['B8']  = f"Avance en el ejercicio del presupuesto {tf['anio']} del Sector Central de AGRICULTURA"
    ws['B9']  = f"Cifras con corte al cierre del {tf['trimestre']} de {tf['anio']}"
    ws['B13'] = f"Cifras con corte al {tf['dia_mes_anio']} 1/ "
    ws['B24'] = f"Fuente: {tf['fuente_map']}"

    def set_row(fila, d):
        orig  = d.get("original_anual", 0) or 0
        mod   = d.get("modificado_anual", 0) or 0
        mod_p = d.get("modificado_p", d.get("original_p", 0)) or 0
        ejrc  = d.get("ejercido", 0) or 0
        ws.cell(fila, 4).value = orig
        ws.cell(fila, 5).value = mod
        ws.cell(fila, 6).value = _var(orig, mod)
        ws.cell(fila, 7).value = mod_p
        ws.cell(fila, 8).value = ejrc
        ws.cell(fila, 9).value = _var(mod_p, ejrc)

    # Tabla global cap (filas 18-22) + Total(23) + R27 (total repetido sin etiqueta)
    for c, fila in [(1000,18),(2000,19),(3000,20),(4000,21),(7000,22)]:
        set_row(fila, cap.get(c, {}))
    set_row(23, pp.get("Total general", {}))
    set_row(27, pp.get("Total general", {}))  # fila 27 = total sin encabezado (en plantilla)

    # Tablas por Pp (filas por plantilla de Libro2)
    configs = [
        ("P021", [(1000,32),(2000,33),(3000,34),(4000,35)], 36),
        ("M001", [(1000,41),(2000,42),(3000,43)], 44),
        ("K017", [(7000,55)], 56),
        ("S292", [(1000,62),(2000,63),(3000,64),(4000,65)], 66),
        ("S293", [(2000,72),(3000,73),(4000,74)], 75),
        ("S304", [(4000,81)], 82),
        ("S318", [(4000,88)], 89),
    ]
    from openpyxl.styles import Font, PatternFill
    COLOR_TOTAL_CAP = "BC955C"

    CAP_DENOM = {1000:"Servicios Personales", 2000:"Materiales y Suministros",
                 3000:"Servicios Generales",
                 4000:"Transferencias, asignaciones, subsidios y otras ayudas",
                 7000:"Inversiones financieras y otras provisiones"}

    for pp_k, cap_filas, total_fila in configs:
        for c, fila in cap_filas:
            set_row(fila, pc.get((pp_k, c), {}))
            ws.cell(fila, 1).value = f"{pp_k}{c}"
            ws.cell(fila, 2).value = c
            # Col C puede estar combinada — desmerge antes de escribir
            for mg in list(ws.merged_cells.ranges):
                if mg.min_row <= fila <= mg.max_row and mg.min_col <= 3 <= mg.max_col:
                    ws.unmerge_cells(str(mg))
            ws.cell(fila, 3).value = CAP_DENOM.get(c, '')
            # Limpiar fill/bold heredado del template
            for col_idx in range(1, 10):
                cell = ws.cell(fila, col_idx)
                cell.fill = PatternFill(fill_type=None)
                if cell.font:
                    cell.font = Font(name=cell.font.name, size=cell.font.size,
                                     bold=False, color=cell.font.color.rgb
                                     if cell.font.color and cell.font.color.type == 'rgb'
                                     else '000000')
        # Fila Total: fill café, bold
        ws.cell(total_fila, 1).value = None
        ws.cell(total_fila, 2).value = "Total"
        # Desmerge col C si está combinada
        for mg in list(ws.merged_cells.ranges):
            if mg.min_row <= total_fila <= mg.max_row and mg.min_col <= 3 <= mg.max_col:
                ws.unmerge_cells(str(mg))
        ws.cell(total_fila, 3).value = None
        set_row(total_fila, pp.get(pp_k, {}))
        for col_idx in range(1, 10):
            cell = ws.cell(total_fila, col_idx)
            cell.fill = PatternFill('solid', fgColor=COLOR_TOTAL_CAP)
            cell.font = Font(name=cell.font.name if cell.font else 'Calibri',
                             size=cell.font.size if cell.font else 11,
                             bold=True)

    if 'Pp y CAP' in wb_out.sheetnames: del wb_out['Pp y CAP']
    ws_n = wb_out.create_sheet('Pp y CAP')
    _copy_sheet(ws, ws_n)

# ══════════════════════════════════════════════════════════════════════
#  HOJA AGRICULTURA
# ══════════════════════════════════════════════════════════════════════

def hoja_agricultura(wb_out, datos, tf, tpl):
    wb = _get_template(tpl)
    ws = wb['AGRICULTURA']
    cap = datos["cap"]
    bloq = datos["bloques"]
    mes_nom = MESES_ES[tf['mes']].upper()

    ws['A3'] = f"AVANCE DEL EJERCICIO PRESUPUESTAL AL MES DE {mes_nom} DE {tf['anio']}, SECTOR CENTRAL"
    ws['H5'] = tf['dia_mes_anio']
    ws['A7'] = f"PRESUPUESTO {tf['anio']}"
    ws['B8'] = f"ANUAL AUTORIZADO {tf['anio']}"
    ws['C8'] = f"ANUAL MODIFICADO {tf['anio']}"
    ws['D8'] = f"PROGRAMADO AL {tf['DIA_MES_ANIO']}"
    ws['E8'] = f"EJERCIDO\nAL {tf['DIA_MES_ANIO']}"
    ws['A16'] = f"Módulo de Adecuaciones Presupuestarias (MAP) {tf['anio']}, cifras al {tf['dia_mes_anio']}."

    # Datos por cap: 1000=9, 2000=10, 3000=11, 4000=12, 7000=13
    n_parts = {1000:4, 2000:4, 3000:5, 4000:4, 7000:0}
    for c, fila in [(1000,9),(2000,10),(3000,11),(4000,12),(7000,13)]:
        d = cap.get(c, {})
        orig  = d.get("original_anual", 0) or 0
        mod   = d.get("modificado_anual", 0) or 0
        mod_p = d.get("modificado_p", d.get("original_p", 0)) or 0
        ejrc  = d.get("ejercido", 0) or 0
        disp  = d.get("disponible", mod_p - ejrc) or 0

        ws.cell(fila, 1).value = c
        ws.cell(fila, 2).value = orig
        ws.cell(fila, 3).value = mod
        ws.cell(fila, 4).value = mod_p
        ws.cell(fila, 5).value = ejrc
        ws.cell(fila, 6).value = round(ejrc / mod_p, 6) if mod_p else 0
        ws.cell(fila, 7).value = disp

        if c == 7000:
            mot = ("El Disponible en el Capítulo 7000 Inversiones Financieras y otras "
                   "Provisiones se encuentra en el Pp K017 Infraestructura para el "
                   "desarrollo rural sustentable.")
        elif c == 4000:
            mot = motivo_cap4000(datos, tf)
        else:
            mot = motivo_cap(bloq.get(c, {}), n_parts[c])
        ws.cell(fila, 8).value = mot

    # Total fila 14: sumas de filas 9-13
    for col in range(2, 8):
        ws.cell(14, col).value = sum(ws.cell(r, col).value or 0 for r in range(9, 14))
    # % total = ejercido/programado
    tot_mod_p = ws.cell(14, 4).value or 0
    tot_ejrc  = ws.cell(14, 5).value or 0
    ws.cell(14, 6).value = round(tot_ejrc / tot_mod_p, 6) if tot_mod_p else 0

    if 'AGRICULTURA' in wb_out.sheetnames: del wb_out['AGRICULTURA']
    ws_n = wb_out.create_sheet('AGRICULTURA')
    _copy_sheet(ws, ws_n)

# ══════════════════════════════════════════════════════════════════════
#  HOJA PRESUPUESTO COMISARIO
# ══════════════════════════════════════════════════════════════════════

def hoja_comisario(wb_out, datos, tf, tpl):
    wb = _get_template(tpl)
    ws = wb['Presupuesto Comisario']
    pp   = datos["pp"]
    cap  = datos["cap"]
    bloq = datos["bloques"]

    ws['B4'] = (f"REPORTE DEL EJERCICIO PRESUPUESTAL {tf['anio']}\n"
                f"(PERIODO 1 DE ENERO AL {tf['DIA_MES_ANIO']})")
    ws['E7'] = (f"\nPresupuesto\n1 enero al {tf['dia_mes_anio']}\n(millones de pesos)")
    ws['E8'] = f"Presupuesto Autorizado\n1 al {tf['dia_mes_anio']}"
    ws['F8'] = f"Presupuesto Programado\n1 al {tf['dia_mes_anio']}\n"
    ws['G8'] = f"Presupuesto\n Ejercido\n1 al {tf['dia_mes_anio']}\n"
    ws['H7'] = f"Variación (%) entre lo programado y ejercido\n1 al {tf['dia_mes_anio']}"
    ws['B17'] = f"Fuente: {tf['fuente_map']}"

    # ── Encabezados segunda tabla (capítulos, cols L-R) ───────────────
    ws['N7'] = (f"Presupuesto\n1 al {tf['dia_mes_anio']}\n(millones de pesos)")
    ws['N8'] = f"Presupuesto Autorizado\n1 al {tf['dia_mes_anio']}"
    ws['O8'] = f"Presupuesto Programado\n1 al {tf['dia_mes_anio']}"
    ws['P8'] = f"Presupuesto\n Ejercido\n1 al {tf['dia_mes_anio']}"
    ws['Q7'] = (f"Variación (%) entre lo programado y ejercido\n"
                f"1 al {tf['dia_mes_anio']}")

    # ── Tabla 1: datos por Pp (cols A-I, filas 9-15) ─────────────────
    bloques_pp = datos.get("bloques_pp", {})
    for pp_k, fila in [("M001",9),("P021",10),("K017",11),
                        ("S292",12),("S293",13),("S304",14),("S318",15)]:
        d = pp.get(pp_k, {})
        orig_a = d.get("original_anual", 0) or 0
        mod_a  = d.get("modificado_anual", 0) or 0
        orig_p = d.get("original_p", d.get("modificado_p", 0)) or 0
        mod_p  = d.get("modificado_p", 0) or 0
        ejrc   = d.get("ejercido", 0) or 0

        # Tipo de Pp: primera letra de la clave (M, P, K, S)
        tipo_letra = pp_k[0]

        # Col A: solo la letra del tipo
        try: ws.cell(fila, 1).value = tipo_letra
        except: pass

        # Col B: "letra espacio clave - denominación" (viene del template, solo agregamos prefijo)
        try:
            b_actual = ws.cell(fila, 2).value or ''
            if b_actual and not str(b_actual).startswith(tipo_letra + ' '):
                ws.cell(fila, 2).value = f"{tipo_letra} {b_actual}"
        except: pass

        # Cuando orig_p es 0 Y orig_anual también es 0 → S318 sin presupuesto → dejar blancos
        sin_datos = (orig_a == 0 and orig_p == 0)
        if sin_datos:
            ws.cell(fila, 3).value = None   # C: sin ppto autorizado
            ws.cell(fila, 4).value = mod_a if mod_a else None   # D: modificado anual si existe
            ws.cell(fila, 5).value = None   # E: sin original_p
            ws.cell(fila, 6).value = mod_p if mod_p else None   # F: modificado_p si existe
            ws.cell(fila, 7).value = None   # G: sin ejercido
            ws.cell(fila, 8).value = 0.0    # H: 0.0% variación
        else:
            ws.cell(fila, 3).value = orig_a
            ws.cell(fila, 4).value = mod_a
            ws.cell(fila, 5).value = orig_p
            ws.cell(fila, 6).value = mod_p
            ws.cell(fila, 7).value = ejrc
            ws.cell(fila, 8).value = _var(mod_p, ejrc)

        # Col I: justificación con % correcto del TD Comisario por Pp
        if pp_k == "K017":
            mot = "La variación se encuentra en la partida 79902 Provisiones para erogaciones especiales."
        elif pp_k in ["S304","S318"]:
            mot = "La variación se encuentra en la partida 43101 Subsidios a la producción."
        elif pp_k in ["S292","S293"]:
            bp = bloques_pp.get(pp_k, {})
            # S293 no tiene pct_total, tomar top-3 (da 90.9%)
            n_pp = 3 if not bp.get('pct_total') else 5
            if bp and bp.get('partidas'):
                mot = motivo_pp(bp, n_pp)
            else:
                mot = "La variación se encuentra en la partida 43101 Subsidios a la producción."
        else:
            # M001, P021: pct_total del TD Comisario por Pp, top-5
            bp = bloques_pp.get(pp_k, {})
            if bp and bp.get('partidas'):
                mot = motivo_pp(bp, 5)
            else:
                mot = motivo_cap(bloq.get(1000, {}), 5)
        ws.cell(fila, 9).value = mot

    # (cuadro 2 se escribe después de _copy_sheet — ver abajo)

    if 'Presupuesto Comisario' in wb_out.sheetnames: del wb_out['Presupuesto Comisario']
    ws_n = wb_out.create_sheet('Presupuesto Comisario')
    _copy_sheet(ws, ws_n)

    # ── Tabla 2 se escribe DESPUÉS del copy para sobreescribir
    #    las fórmulas VLOOKUP del template que referencian archivo externo ──
    cap_com = datos.get("cap_com", {})
    bloq    = datos.get("bloques", {})
    n_parts_com = {1000:5, 2000:4, 3000:5, 4000:4, 7000:0}

    for cap_k, fila in [(1000,9),(2000,10),(3000,11),(4000,12),(7000,13)]:
        dc    = cap_com.get(cap_k, {})
        ori_p = dc.get("original_p", 0) or 0
        mod_p = dc.get("modificado_p", 0) or 0
        ejrc  = dc.get("ejercido", 0) or 0

        FMT_N = '_-* #,##0.00_-;\\-* #,##0.00_-;_-* "-"??_-;_-@_-'
        for col, val, fmt in [
            (14, ori_p,              FMT_N),
            (15, mod_p,              FMT_N),
            (16, ejrc,               FMT_N),
            (17, _var(mod_p, ejrc),  '0.0%'),
        ]:
            c = ws_n.cell(fila, col)
            c.value = val
            c.number_format = fmt

        # Col R: motivos de variación
        if cap_k == 7000:
            mot2 = "79902 Provisiones para erogaciones especiales."
        elif cap_k == 4000:
            mot2 = "El 100 % de la variación en los recursos se observa en la partida:\n43101 Subsidios a la Producción"
        else:
            mot2 = motivo_cap(bloq.get(cap_k, {}), n_parts_com[cap_k])
        ws_n.cell(fila, 18).value = mot2

# ══════════════════════════════════════════════════════════════════════
#  FUNCIÓN PRINCIPAL
# ══════════════════════════════════════════════════════════════════════

def generar_cuadros(ruta_entrada: str, ruta_salida: str = None,
                    mes_corte: int = None, anio_corte: int = None) -> str:
    """
    Lee la base MAP del día (CSV o xlsx) y genera los 4 cuadros.
    Los templates están embebidos — no se necesitan archivos externos.
    """
    print(f"📂 Leyendo: {ruta_entrada}")

    # Fecha
    if mes_corte and anio_corte:
        fecha = {"dia": DIAS_FIN_MES[mes_corte], "mes": mes_corte, "anio": anio_corte}
    else:
        fecha = detectar_fecha(ruta_entrada)
    tf = textos_fecha(fecha)
    print(f"📅 Fecha de corte: {tf['dia_mes_anio']}")

    # Leer datos
    ext = os.path.splitext(ruta_entrada)[1].lower()
    if ext == '.csv':
        datos = leer_csv_map(ruta_entrada, fecha["mes"])
    else:
        datos = leer_xlsx_map(ruta_entrada)
    datos['_mes'] = fecha["mes"]
    print(f"✅ {len(datos['pp'])-1} Pp, {len(datos['cap'])} capítulos")

    # Templates embebidos — no se necesitan archivos externos
    tpls = {
        'Pp':          TPL_PP,
        'PpCAP':       TPL_PPCAP,
        'AGRICULTURA': TPL_AGR,
        'Comisario':   TPL_COM,
    }

    wb_out = openpyxl.Workbook()
    if "Sheet" in wb_out.sheetnames: del wb_out["Sheet"]

    print("📊 Generando Pp...")
    hoja_pp(wb_out, datos, tf, tpls['Pp'])

    print("📊 Generando Pp y CAP...")
    hoja_pp_cap(wb_out, datos, tf, tpls['PpCAP'])

    print("📊 Generando AGRICULTURA...")
    hoja_agricultura(wb_out, datos, tf, tpls['AGRICULTURA'])

    print("📊 Generando Presupuesto Comisario...")
    hoja_comisario(wb_out, datos, tf, tpls['Comisario'])

    # Salida
    if ruta_salida is None:
        mes_str = MESES_ES[fecha["mes"]].upper()
        nombre_out = f"CUADROS_COCODI_{fecha['dia']:02d}-{mes_str}-{fecha['anio']}.xlsx"
        carpeta = os.getcwd()
        ruta_salida = os.path.join(carpeta, nombre_out)

    wb_out.save(ruta_salida)
    print(f"\n✅ Archivo generado: {ruta_salida}")
    return ruta_salida


# ══════════════════════════════════════════════════════════════════════
#  COLAB
# ══════════════════════════════════════════════════════════════════════

def _colab_main():
    try:
        from google.colab import files as _f
    except ImportError:
        # Fuera de Colab — pedir ruta por terminal
        import sys
        args = [a for a in sys.argv[1:] if not a.startswith('-') and not a.endswith('.json')]
        if args:
            generar_cuadros(args[0])
        else:
            ruta = input("📂 Ruta del archivo MAP (.csv o .xlsx): ").strip()
            if ruta:
                generar_cuadros(ruta)
        return

    print("═" * 55)
    print("  GENERADOR DE CUADROS COCODI — SADER MAP 2026")
    print("═" * 55)
    print()
    print("📂 Selecciona el archivo MAP del día (.csv o .xlsx):")
    sub = _f.upload()
    if not sub:
        print("⚠️  No se subió ningún archivo.")
        return

    nombre, contenido = next(iter(sub.items()))
    ruta = f"/content/{nombre}"
    with open(ruta, "wb") as f:
        f.write(contenido)

    print()
    ruta_out = generar_cuadros(ruta)
    print()
    print("⬇️  Descargando archivo generado...")
    _f.download(ruta_out)
    print()
    print("✅ ¡Listo! Revisa tu carpeta de descargas.")


if __name__ == "__main__":
    _colab_main()
